#!/usr/bin/env python3
"""Register update from the 19 Oct 2026 research deep dives (audit/research_2026-10-19/A–F, rounds 1 and 2)
and the power-bill research (audit/template_ideas_2026-10-19.md). Idempotent: new ids are replaced, edits are set.
Every figure here was read in the research files; confidences follow the round 2 skeptic check."""
import json, os
H = os.path.dirname(os.path.abspath(__file__))
P = os.path.join(H, 'formula_register.json')
d = json.load(open(P, encoding='utf-8'))
Q = {q['id']: q for q in d['quantities']}
S = d['new_sources']
R = 'audit/research_2026-10-19/'

def src(i, t): S[i] = t
def role(i, term, r, c, v=True): return {'id': i, 'term': term, 'role': r, 'conf': c, 'verified': v}
def add(i, name, unit, stage, inputs, formula, coef, sources, conf, status, roles):
    q = {'id': i, 'name': name, 'unit': unit, 'formula': formula, 'inputs': inputs, 'coef': coef, 'sources': sources,
         'conf': conf, 'status': status, 'stage': stage, 'source_roles': roles, 'added': '2026-10-19'}
    if i in Q: d['quantities'][d['quantities'].index(Q[i])] = q
    else: d['quantities'].append(q)
    Q[i] = q
def edit(i, **kw):
    q = Q[i]
    for k, v in kw.items():
        if k == 'add_sources': q['sources'] = q['sources'] + [x for x in v if x not in q['sources']]
        elif k == 'add_roles': q['source_roles'] = [r for r in q.get('source_roles', []) if r['id'] not in {x['id'] for x in v}] + v
        else: q[k] = v
    q['revised'] = '2026-10-19'

